// Copies the MediaPipe Pose runtime (script, WASM, model) from node_modules
// into public/ so the camera workout loads it from our own origin instead of
// cdn.jsdelivr.net (blocked or slow on some school/office networks).
//
// Output: public/mediapipe/pose/<version>/  (gitignored — regenerated by the
// predev / prebuild npm hooks). The version folder makes the URL immutable,
// so the service worker and HTTP cache can keep it forever and an upgrade
// can never mix an old pose.js with a new .wasm.
//
// The 27 MB "heavy" model is skipped: the app only uses complexity 0 (lite)
// and 1 (full).
import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const src = path.join(root, 'node_modules', '@mediapipe', 'pose');
const outRoot = path.join(root, 'public', 'mediapipe', 'pose');

if (!existsSync(src)) {
  // Not fatal: the app falls back to the CDN when local files are missing.
  console.warn('[copy-mediapipe] @mediapipe/pose not installed — skipping (CDN fallback will be used).');
  process.exit(0);
}

const { version } = JSON.parse(readFileSync(path.join(src, 'package.json'), 'utf8'));
const out = path.join(outRoot, version);

const SKIP = new Set(['package.json', 'README.md', 'index.d.ts', 'pose_landmark_heavy.tflite']);
const files = readdirSync(src).filter((f) => !SKIP.has(f) && statSync(path.join(src, f)).isFile());

// Drop folders left by older versions so stale runtimes are never deployed.
if (existsSync(outRoot)) {
  for (const dir of readdirSync(outRoot)) {
    if (dir !== version) rmSync(path.join(outRoot, dir), { recursive: true, force: true });
  }
}
mkdirSync(out, { recursive: true });

let copied = 0;
for (const f of files) {
  const from = path.join(src, f);
  const to = path.join(out, f);
  if (existsSync(to) && statSync(to).size === statSync(from).size) continue;
  copyFileSync(from, to);
  copied += 1;
}
console.log(`[copy-mediapipe] pose ${version}: ${copied} copied, ${files.length - copied} up to date → public/mediapipe/pose/${version}/`);
